begin;

create table public.marketplace_live_affiliate_offers(
 id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.marketplace_sellers(user_id),store_id uuid not null references public.marketplace_stores(id),product_id uuid not null references public.products(id),creator_id uuid references auth.users(id),offer_scope text not null check(offer_scope in('public_creator','specific_creator')),commission_bps integer not null check(commission_bps between 1 and 3000),status text not null default 'active' check(status in('active','paused','removed')),starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((offer_scope='public_creator'and creator_id is null)or(offer_scope='specific_creator'and creator_id is not null)),check(ends_at is null or starts_at is null or ends_at>starts_at)
);
create unique index marketplace_live_offer_active_unique on public.marketplace_live_affiliate_offers(product_id,coalesce(creator_id,'00000000-0000-0000-0000-000000000000'::uuid))where status='active';

alter table public.live_session_products drop constraint live_pin_host_seller;
alter table public.live_session_products add column commerce_mode text not null default 'own_product' check(commerce_mode in('own_product','affiliate_product')),add column creator_commission_bps integer not null default 0 check(creator_commission_bps between 0 and 3000),add column affiliate_offer_id uuid references public.marketplace_live_affiliate_offers(id);
alter table public.live_session_products add constraint live_pin_commission_mode_check check((commerce_mode='own_product'and creator_commission_bps=0 and affiliate_offer_id is null and host_id=seller_id)or(commerce_mode='affiliate_product'and creator_commission_bps>0 and affiliate_offer_id is not null and host_id<>seller_id));

create table public.marketplace_live_commission_sources(
 id uuid primary key default gen_random_uuid(),checkout_id uuid not null references public.marketplace_checkout_sessions(id),order_id uuid not null unique references public.marketplace_orders(id),payment_id uuid not null references public.marketplace_payments(id),allocation_id uuid not null unique references public.marketplace_payment_allocations(id),live_session_id uuid not null references public.live_sessions(id),host_id uuid not null references auth.users(id),seller_id uuid not null references public.marketplace_sellers(user_id),store_id uuid not null references public.marketplace_stores(id),product_id uuid not null references public.products(id),variant_id uuid not null references public.marketplace_product_variants(id),affiliate_offer_id uuid references public.marketplace_live_affiliate_offers(id),commerce_mode text not null check(commerce_mode in('own_product','affiliate_product')),creator_commission_bps integer not null check(creator_commission_bps between 0 and 3000),creator_commission_amount numeric(20,8) not null,currency text not null default 'BDAG' check(currency='BDAG'),created_at timestamptz not null default now(),check(creator_commission_amount>=0 and creator_commission_amount=round(creator_commission_amount,8)),check((commerce_mode='own_product'and affiliate_offer_id is null and creator_commission_bps=0 and creator_commission_amount=0 and host_id=seller_id)or(commerce_mode='affiliate_product'and affiliate_offer_id is not null and creator_commission_bps>0 and creator_commission_amount>0 and host_id<>seller_id))
);

create table public.live_commerce_purchase_events(
 id uuid primary key default gen_random_uuid(),session_id uuid not null references public.live_sessions(id),host_id uuid not null references auth.users(id),buyer_id uuid not null references auth.users(id),checkout_id uuid not null references public.marketplace_checkout_sessions(id),order_id uuid not null unique references public.marketplace_orders(id),order_item_id uuid not null references public.marketplace_order_items(id),product_id uuid not null references public.products(id),variant_id uuid not null references public.marketplace_product_variants(id),quantity integer not null check(quantity>0),currency text not null default 'BDAG' check(currency='BDAG'),gross_amount numeric(20,8) not null check(gross_amount>0),creator_commission_amount numeric(20,8) not null default 0 check(creator_commission_amount>=0),creator_commission_status text not null check(creator_commission_status in('none','held','released')),buyer_display_name text not null check(char_length(btrim(buyer_display_name))between 1 and 80),created_at timestamptz not null default now()
);
create index live_purchase_events_host_idx on public.live_commerce_purchase_events(session_id,created_at desc);

alter table public.marketplace_payment_allocations add column creator_user_id uuid references auth.users(id),add column creator_commission_amount numeric(20,8) not null default 0;
alter table public.marketplace_payment_allocations drop constraint marketplace_payment_allocations_check2;
alter table public.marketplace_payment_allocations add constraint marketplace_allocation_split_check check(gross_amount=platform_fee_amount+seller_net_amount+creator_commission_amount and creator_commission_amount>=0 and creator_commission_amount=round(creator_commission_amount,8) and ((creator_commission_amount=0 and creator_user_id is null)or(creator_commission_amount>0 and creator_user_id is not null)));

alter table public.marketplace_order_settlements add column creator_user_id uuid references auth.users(id),add column creator_commission_amount numeric(20,8) not null default 0;
alter table public.marketplace_order_settlements drop constraint marketplace_settlement_amount_check;
alter table public.marketplace_order_settlements add constraint marketplace_settlement_amount_check check(gross_amount>0 and seller_net_amount>=0 and platform_fee_amount>=0 and creator_commission_amount>=0 and gross_amount=round(gross_amount,8) and seller_net_amount=round(seller_net_amount,8) and platform_fee_amount=round(platform_fee_amount,8) and creator_commission_amount=round(creator_commission_amount,8) and gross_amount=seller_net_amount+platform_fee_amount+creator_commission_amount and ((creator_commission_amount=0 and creator_user_id is null)or(creator_commission_amount>0 and creator_user_id is not null)));

create or replace function public.upsert_my_live_affiliate_offer(p_product_id uuid,p_offer_scope text,p_creator_id uuid,p_commission_bps integer,p_status text)returns jsonb language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();p public.products;s public.marketplace_stores;r public.marketplace_live_affiliate_offers;begin if actor is null then raise exception using errcode='42501',message='marketplace_auth_required';end if;select*into p from public.products where id=p_product_id and seller_id=actor;select*into s from public.marketplace_stores where id=p.store_id and seller_id=actor and status='active';if p.id is null or s.id is null or not exists(select 1 from public.marketplace_sellers where user_id=actor and status='approved')or p.status<>'active'or p.moderation_status<>'approved'or p.deleted_at is not null or p.product_type<>'physical'or p.currency<>'BDAG'then raise exception using message='live_affiliate_product_unavailable';end if;if p_offer_scope not in('public_creator','specific_creator')or p_status not in('active','paused','removed')or p_commission_bps not between 1 and 3000 or(p_offer_scope='public_creator'and p_creator_id is not null)or(p_offer_scope='specific_creator'and p_creator_id is null)then raise exception using message='live_affiliate_invalid_offer';end if;update public.marketplace_live_affiliate_offers set status='removed',updated_at=now()where product_id=p.id and status='active'and coalesce(creator_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(p_creator_id,'00000000-0000-0000-0000-000000000000'::uuid);insert into public.marketplace_live_affiliate_offers(seller_id,store_id,product_id,creator_id,offer_scope,commission_bps,status)values(actor,s.id,p.id,p_creator_id,p_offer_scope,p_commission_bps,p_status)returning*into r;return jsonb_build_object('id',r.id,'product_id',r.product_id,'offer_scope',r.offer_scope,'creator_id',r.creator_id,'commission_bps',r.commission_bps,'status',r.status);end$$;

create or replace function public.pin_live_session_product(p_session_id uuid,p_product_id uuid,p_featured_variant_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();fingerprint text;prior public.live_commerce_commands;c record;p public.products;v public.marketplace_product_variants;r public.live_session_products;result jsonb;offer public.marketplace_live_affiliate_offers;mode text;bps integer;begin if actor is null or p_session_id is null or p_product_id is null or p_idempotency_key is null then raise exception using message='live_commerce_invalid_input';end if;fingerprint:=encode(extensions.digest(concat_ws('|','pin',p_session_id,p_product_id,coalesce(p_featured_variant_id::text,'')),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_idempotency_key::text,0));select*into prior from public.live_commerce_commands where actor_id=actor and idempotency_key=p_idempotency_key;if found then if prior.request_fingerprint<>fingerprint then raise exception using message='live_commerce_idempotency_conflict';end if;return prior.result_json;end if;select*into c from public.live_commerce_host_context(p_session_id);perform pg_advisory_xact_lock(hashtextextended('live-pin:'||p_session_id,0));select*into p from public.products where id=p_product_id;if not found or p.status<>'active'or p.moderation_status<>'approved'or p.product_type<>'physical'or p.currency<>'BDAG'or p.deleted_at is not null or not exists(select 1 from public.marketplace_stores st join public.marketplace_sellers ms on ms.user_id=st.seller_id where st.id=p.store_id and st.seller_id=p.seller_id and st.status='active'and ms.status='approved')then raise exception using message='live_commerce_product_unavailable';end if;if p.seller_id=actor then mode:='own_product';bps:=0;else select*into offer from public.marketplace_live_affiliate_offers where product_id=p.id and seller_id=p.seller_id and store_id=p.store_id and status='active'and(starts_at is null or starts_at<=now())and(ends_at is null or ends_at>now())and(offer_scope='public_creator'or creator_id=actor)order by(creator_id=actor)desc,created_at desc limit 1;if not found then raise exception using message='live_affiliate_not_authorized';end if;mode:='affiliate_product';bps:=offer.commission_bps;end if;if p_featured_variant_id is not null and not exists(select 1 from public.marketplace_product_variants where id=p_featured_variant_id and product_id=p.id and status='active'and archived_at is null)then raise exception using message='live_commerce_invalid_variant';end if;if not exists(select 1 from public.marketplace_product_variants x join public.marketplace_inventory_levels i on i.variant_id=x.id where x.product_id=p.id and x.status='active'and x.archived_at is null and i.on_hand>i.reserved)then raise exception using message='live_commerce_out_of_stock';end if;select*into r from public.live_session_products where session_id=p_session_id and product_id=p.id and status='active';if not found then if(select count(*)from public.live_session_products where session_id=p_session_id and status='active')>=20 then raise exception using message='live_commerce_pin_limit';end if;insert into public.live_session_products(session_id,host_id,seller_id,store_id,product_id,featured_variant_id,is_featured,position,commerce_mode,creator_commission_bps,affiliate_offer_id)values(p_session_id,actor,p.seller_id,p.store_id,p.id,p_featured_variant_id,false,(select count(*)from public.live_session_products where session_id=p_session_id and status='active'),mode,bps,offer.id)returning*into r;end if;result:=jsonb_build_object('id',r.id,'status',r.status,'is_featured',r.is_featured,'commerce_mode',r.commerce_mode,'creator_commission_bps',r.creator_commission_bps);insert into public.live_commerce_commands(actor_id,session_id,command_type,idempotency_key,request_fingerprint,result_json)values(actor,p_session_id,'pin',p_idempotency_key,fingerprint,result);return result;end$$;

create or replace function public.feature_live_session_product(p_session_id uuid,p_live_session_product_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();fingerprint text;prior public.live_commerce_commands;c record;r public.live_session_products;result jsonb;begin if actor is null or p_session_id is null or p_live_session_product_id is null or p_idempotency_key is null then raise exception using message='live_commerce_invalid_input';end if;fingerprint:=encode(extensions.digest(concat_ws('|','feature',p_session_id,p_live_session_product_id),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_idempotency_key::text,0));select*into prior from public.live_commerce_commands where actor_id=actor and idempotency_key=p_idempotency_key;if found then if prior.request_fingerprint<>fingerprint then raise exception using message='live_commerce_idempotency_conflict';end if;return prior.result_json;end if;select*into c from public.live_commerce_host_context(p_session_id);perform pg_advisory_xact_lock(hashtextextended('live-feature:'||p_session_id,0));select*into r from public.live_session_products where id=p_live_session_product_id and session_id=p_session_id and status='active'for update;if not found then raise exception using message='live_commerce_pin_not_found';end if;if not exists(select 1 from public.products p join public.marketplace_stores st on st.id=p.store_id and st.status='active'join public.marketplace_sellers ms on ms.user_id=p.seller_id and ms.status='approved'join public.marketplace_product_variants v on v.product_id=p.id and v.status='active'and v.archived_at is null join public.marketplace_inventory_levels i on i.variant_id=v.id and i.on_hand>i.reserved where p.id=r.product_id and p.status='active'and p.moderation_status='approved'and p.deleted_at is null and p.product_type='physical'and p.currency='BDAG')or(r.commerce_mode='affiliate_product'and not exists(select 1 from public.marketplace_live_affiliate_offers o where o.id=r.affiliate_offer_id and o.status='active'and(o.starts_at is null or o.starts_at<=now())and(o.ends_at is null or o.ends_at>now())and(o.offer_scope='public_creator'or o.creator_id=actor)))then raise exception using message='live_commerce_product_unavailable';end if;update public.live_session_products set is_featured=(id=r.id),version=version+1 where session_id=p_session_id and status='active'and is_featured is distinct from(id=r.id);result:=jsonb_build_object('id',r.id,'is_featured',true);insert into public.live_commerce_commands(actor_id,session_id,command_type,idempotency_key,request_fingerprint,result_json)values(actor,p_session_id,'feature',p_idempotency_key,fingerprint,result);return result;end$$;

create or replace function public.marketplace_apply_live_commission()returns trigger language plpgsql set search_path=public as $$declare src public.marketplace_live_order_sources;pin public.live_session_products;commission numeric(20,8);begin select*into src from public.marketplace_live_order_sources where order_id=new.order_id; if not found then new.creator_user_id:=null;new.creator_commission_amount:=0;return new;end if;select*into pin from public.live_session_products where id=src.live_session_product_id;if pin.commerce_mode='affiliate_product'then commission:=round(new.gross_amount*pin.creator_commission_bps/10000.0,8);if commission<=0 or commission>new.gross_amount-new.platform_fee_amount then raise exception using message='marketplace_live_commission_integrity_error';end if;new.creator_user_id:=pin.host_id;new.creator_commission_amount:=commission;new.seller_net_amount:=new.gross_amount-new.platform_fee_amount-commission;else new.creator_user_id:=null;new.creator_commission_amount:=0;end if;return new;end$$;
create trigger marketplace_allocation_live_commission before insert on public.marketplace_payment_allocations for each row execute function public.marketplace_apply_live_commission();

create or replace function public.marketplace_record_live_purchase()returns trigger language plpgsql security definer set search_path=public as $$declare src public.marketplace_live_order_sources;pin public.live_session_products;item public.marketplace_order_items;buyer_name text;begin select*into src from public.marketplace_live_order_sources where order_id=new.order_id;if not found then return new;end if;select*into pin from public.live_session_products where id=src.live_session_product_id;select*into item from public.marketplace_order_items where order_id=new.order_id order by created_at limit 1;select coalesce(nullif(btrim(display_name),''),username,'Comprador')into buyer_name from public.user_profiles where id=src.buyer_id;insert into public.marketplace_live_commission_sources(checkout_id,order_id,payment_id,allocation_id,live_session_id,host_id,seller_id,store_id,product_id,variant_id,affiliate_offer_id,commerce_mode,creator_commission_bps,creator_commission_amount)values(new.checkout_id,new.order_id,new.payment_id,new.id,src.live_session_id,src.live_host_id,new.seller_id,new.store_id,src.product_id,src.variant_id,pin.affiliate_offer_id,pin.commerce_mode,pin.creator_commission_bps,new.creator_commission_amount);insert into public.live_commerce_purchase_events(session_id,host_id,buyer_id,checkout_id,order_id,order_item_id,product_id,variant_id,quantity,gross_amount,creator_commission_amount,creator_commission_status,buyer_display_name)values(src.live_session_id,src.live_host_id,src.buyer_id,new.checkout_id,new.order_id,item.id,item.product_id,item.variant_id,item.quantity,new.gross_amount,new.creator_commission_amount,case when new.creator_commission_amount>0 then'held'else'none'end,left(buyer_name,80));return new;end$$;
create trigger marketplace_allocation_record_live_purchase after insert on public.marketplace_payment_allocations for each row execute function public.marketplace_record_live_purchase();

create or replace function public.fetch_my_live_purchase_events(p_session_id uuid,p_limit integer default 50)returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'buyer_display_name',e.buyer_display_name,'product_title',i.product_title,'quantity',e.quantity,'gross_amount',e.gross_amount,'creator_commission_amount',e.creator_commission_amount,'creator_commission_status',case when e.creator_commission_amount=0 then'none'when a.status='released'then'released'else'held'end,'created_at',e.created_at)order by e.created_at desc),'[]'::jsonb)from(select*from public.live_commerce_purchase_events where session_id=p_session_id and host_id=auth.uid()order by created_at desc limit least(greatest(coalesce(p_limit,50),1),100))e join public.marketplace_order_items i on i.id=e.order_item_id join public.marketplace_payment_allocations a on a.order_id=e.order_id$$;

create or replace function public.live_commerce_host_context(p_session uuid)returns table(host_id uuid,store_id uuid)language plpgsql security definer set search_path=public as $$begin if auth.uid()is null then raise exception using errcode='42501',message='live_commerce_auth_required';end if;return query select l.host_id,(select s.id from public.marketplace_stores s join public.marketplace_sellers ms on ms.user_id=s.seller_id where s.seller_id=l.host_id and s.status='active'and ms.status='approved'order by s.created_at limit 1)from public.live_sessions l where l.id=p_session and l.status='live'and l.host_id=auth.uid();if not found then raise exception using errcode='42501',message='live_commerce_host_not_eligible';end if;end$$;

create or replace function public.fetch_my_live_product_candidates(p_session_id uuid,p_limit integer default 20,p_before_updated_at timestamptz default null,p_before_id uuid default null)returns jsonb language plpgsql stable security definer set search_path=public as $$
declare c record;n integer:=least(greatest(coalesce(p_limit,20),1),50);rows_json jsonb;extra boolean;
begin
 if(p_before_updated_at is null)<>(p_before_id is null)then raise exception using message='live_commerce_invalid_cursor';end if;
 select*into c from public.live_commerce_host_context(p_session_id);
 with affiliate as(
  select distinct on(p.id)p.id,p.store_id,st.name store_name,p.title,public.marketplace_safe_public_image_url(p.images[1])image_url,p.updated_at,'affiliate_product'::text commerce_mode,o.commission_bps
  from public.marketplace_live_affiliate_offers o join public.products p on p.id=o.product_id join public.marketplace_stores st on st.id=o.store_id and st.status='active'join public.marketplace_sellers ms on ms.user_id=o.seller_id and ms.status='approved'
  where p.seller_id<>c.host_id and o.status='active'and(o.starts_at is null or o.starts_at<=now())and(o.ends_at is null or o.ends_at>now())and(o.offer_scope='public_creator'or o.creator_id=c.host_id)and p.status='active'and p.moderation_status='approved'and p.deleted_at is null and p.product_type='physical'and p.currency='BDAG'
  order by p.id,(o.creator_id=c.host_id)desc,o.created_at desc
 ),eligible as(
  select p.id,p.store_id,st.name store_name,p.title,public.marketplace_safe_public_image_url(p.images[1])image_url,p.updated_at,'own_product'::text commerce_mode,0 commission_bps
  from public.products p join public.marketplace_stores st on st.id=p.store_id and st.status='active'join public.marketplace_sellers ms on ms.user_id=p.seller_id and ms.status='approved'
  where p.seller_id=c.host_id and p.status='active'and p.moderation_status='approved'and p.deleted_at is null and p.product_type='physical'and p.currency='BDAG'
  union all select*from affiliate
 ),candidates as(
  select e.*,min(v.price)min_price,max(v.price)max_price,count(v.id)active_variant_count,coalesce(sum(greatest(i.on_hand-i.reserved,0)),0)available_quantity,pin.id pin_id,(pin.id is not null)is_pinned,coalesce(pin.is_featured,false)is_featured
  from eligible e left join public.marketplace_product_variants v on v.product_id=e.id and v.status='active'and v.archived_at is null left join public.marketplace_inventory_levels i on i.variant_id=v.id left join lateral(select lp.id,lp.is_featured from public.live_session_products lp where lp.session_id=p_session_id and lp.product_id=e.id and lp.status='active'order by lp.pinned_at desc,lp.id desc limit 1)pin on true
  where p_before_updated_at is null or(e.updated_at,e.id)<(p_before_updated_at,p_before_id)group by e.id,e.store_id,e.store_name,e.title,e.image_url,e.updated_at,e.commerce_mode,e.commission_bps,pin.id,pin.is_featured order by e.updated_at desc,e.id desc limit n+1
 ),numbered as(select*,row_number()over(order by updated_at desc,id desc)rn from candidates)
 select coalesce(jsonb_agg(jsonb_build_object('product_id',id,'store_id',store_id,'store_name',store_name,'title',title,'image_url',image_url,'min_price',min_price,'max_price',max_price,'active_variant_count',active_variant_count,'available_quantity',available_quantity,'pin_id',pin_id,'is_pinned',is_pinned,'is_featured',is_featured,'commerce_mode',commerce_mode,'creator_commission_bps',commission_bps,'updated_at',updated_at)order by updated_at desc,id desc)filter(where rn<=n),'[]'::jsonb),bool_or(rn>n)into rows_json,extra from numbered;
 return jsonb_build_object('items',rows_json,'next_cursor',case when coalesce(extra,false)then(select jsonb_build_object('updated_at',x->>'updated_at','id',x->>'product_id')from jsonb_array_elements(rows_json)x order by x->>'updated_at',x->>'product_id'limit 1)else null end);
end$$;

create or replace function public.fetch_live_session_products(p_session_id uuid)returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'product_id',q.product_id,'store_id',q.store_id,'store_name',q.store_name,'seller_name',q.seller_name,'title',q.title,'description',q.description,'image_url',q.image_url,'min_price',q.min_price,'max_price',q.max_price,'compare_at_price',q.compare_at_price,'active_variant_count',q.variant_count,'available_quantity',q.available_quantity,'featured_variant_id',q.safe_featured_variant_id,'is_featured',q.is_featured,'position',q.position,'sold_count',q.sold_count,'availability',case when q.eligible and q.available_quantity>0 then'available'when q.eligible then'out_of_stock'else'product_unavailable'end)order by q.is_featured desc,q.position,q.id),'[]'::jsonb)from(select lp.id,lp.product_id,lp.store_id,lp.featured_variant_id,lp.is_featured,lp.position,st.name store_name,coalesce(up.display_name,up.username)seller_name,p.title,p.description,public.marketplace_safe_public_image_url(p.images[1])image_url,min(v.price)filter(where v.status='active'and v.archived_at is null)min_price,max(v.price)filter(where v.status='active'and v.archived_at is null)max_price,max(v.compare_at_price)filter(where v.status='active'and v.archived_at is null)compare_at_price,count(v.id)filter(where v.status='active'and v.archived_at is null)variant_count,coalesce(sum(greatest(i.on_hand-i.reserved,0))filter(where v.status='active'and v.archived_at is null),0)available_quantity,(array_agg(v.id order by v.id)filter(where v.id=lp.featured_variant_id and v.status='active'and v.archived_at is null and greatest(coalesce(i.on_hand,0)-coalesce(i.reserved,0),0)>0))[1]safe_featured_variant_id,coalesce((select sum(e.quantity)from public.live_commerce_purchase_events e where e.session_id=lp.session_id and e.product_id=lp.product_id),0)sold_count,p.status='active'and p.moderation_status='approved'and p.deleted_at is null and p.product_type='physical'and p.currency='BDAG'and st.status='active'and ms.status='approved'eligible from public.live_session_products lp join public.live_sessions l on l.id=lp.session_id and l.status='live'join public.products p on p.id=lp.product_id join public.marketplace_stores st on st.id=lp.store_id join public.marketplace_sellers ms on ms.user_id=lp.seller_id join public.user_profiles up on up.id=lp.seller_id left join public.marketplace_product_variants v on v.product_id=p.id left join public.marketplace_inventory_levels i on i.variant_id=v.id where lp.session_id=p_session_id and lp.status='active'group by lp.id,st.id,up.id,p.id,ms.user_id)q$$;

alter table public.marketplace_live_affiliate_offers enable row level security;
alter table public.marketplace_live_commission_sources enable row level security;
alter table public.live_commerce_purchase_events enable row level security;
create trigger marketplace_live_commission_source_immutable before update or delete on public.marketplace_live_commission_sources for each row execute function public.reject_marketplace_live_source_mutation();
create trigger live_purchase_event_immutable before update or delete on public.live_commerce_purchase_events for each row execute function public.reject_marketplace_live_source_mutation();
create policy live_purchase_host_read on public.live_commerce_purchase_events for select to authenticated using(host_id=auth.uid());
revoke all on public.marketplace_live_affiliate_offers,public.marketplace_live_commission_sources,public.live_commerce_purchase_events from public,anon,authenticated;
grant select on public.live_commerce_purchase_events to authenticated;
revoke all on function public.upsert_my_live_affiliate_offer(uuid,text,uuid,integer,text),public.fetch_my_live_purchase_events(uuid,integer)from public,anon;
grant execute on function public.upsert_my_live_affiliate_offer(uuid,text,uuid,integer,text),public.fetch_my_live_purchase_events(uuid,integer)to authenticated,service_role;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and schemaname='public'and tablename='live_commerce_purchase_events')then alter publication supabase_realtime add table public.live_commerce_purchase_events;end if;end$$;

commit;
